insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d2027ed3-7670-4963-9212-4e48cccf8097', 'de', 'Was passiert, wenn du an Fäden anknüpfst, statt zu neuen Fragen zu springen?', '["Das Gespräch fühlt sich natürlicher an und weniger wie ein Verhör", "Sie fühlt sich gehört, weil du auf das eingehst, was sie erzählt hat", "Beides"]'::jsonb, 'An Fäden anzuknüpfen zeigt Präsenz und Aufmerksamkeit. Nimm ihr letztes Detail als nächsten Schritt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('999bda2b-2b88-4a84-bd9c-d736ccb07089', 'de', 'Sie sagt: „Ich arbeite im Marketing.“ Welche Antwort knüpft am Faden an?', '["„Cool. Woher kommst du ursprünglich?“", "„Ich hab auch einen Freund im Marketing. Die Welt ist klein.“", "„Oh, schön. Ich arbeite im Finanzbereich.“", "„Marketing ist spannend. Welche Richtung? Social Media, Marke, Analytics?“"]'::jsonb, 'An einem Faden anknüpfen heißt, ihr Thema zu vertiefen. Frag konkret nach dem, was sie erwähnt hat.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2923827f-429f-4dd6-ac88-436a5a9dbbc6', 'de', 'Wie wählst du aus, an welchem Faden du anknüpfst?', '["Ein Detail nehmen, das dich interessiert", "Eine vorbereitete Fragenliste abarbeiten", "Auf etwas Konkretem aufbauen, das sie erzählt hat"]'::jsonb, 'Jedes Detail, das sie dir gibt, kann das Gespräch voranbringen. Nimm das, was dich neugierig macht.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('29feaa96-2d35-4ba5-9ebd-71eb7f487487', 'de', 'Warum kann ein Gespräch angespannt wirken, wenn du nur Fragen stellst?', '["Fragen bremsen das Gespräch", "Mit jeder Frage schiebst du ihr wieder die Verantwortung zu", "Fragen klingen einstudiert", "Fragen verringern die Anziehung"]'::jsonb, 'Zu viele Fragen wirken wie ein Ausfragen, bei dem sie das Gespräch allein trägt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('52edb21f-05cb-41ea-a94c-5ec38eca6a8d', 'de', 'Was leisten Aussagen und Beobachtungen, was Fragen nicht können?', '["Sie zeigen Selbstbewusstsein, weil du deine Sicht teilst", "Sie zeigen, dass du interessant genug bist, um Gedanken beizusteuern", "Sie bieten ihr Anknüpfungspunkte, ohne eine Antwort zu verlangen"]'::jsonb, 'Beobachtungen geben ihr etwas, worauf sie eingehen kann, ohne dass sie antworten muss.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('89a9c6b7-ea88-49ca-a0b1-19c9f94287cd', 'de', 'Welche Antworten sind Beobachtungen oder Aussagen statt Ausfragen?', '["„Sieht aus, als hättest du den Drink gebraucht.“", "„Das klingt anstrengend.“", "„Arbeitest du oft lange?“", "„Hier wird’s am Wochenende echt hektisch.“"]'::jsonb, 'Diese Sätze bringen Kontext oder eine eigene Sicht ein, statt nach mehr Informationen zu fragen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a8dcf867-454f-44e9-b824-f823389b43f0', 'de', 'Was beschreibt guten Gesprächsschwung am besten?', '["Selbstbewusst reden, ohne Pausen", "Sie komplett führen lassen", "Stille so schnell wie möglich füllen", "Ein gleichmäßiges Hin und Her, bei dem beide etwas beitragen"]'::jsonb, 'Schwung entsteht, wenn beide etwas beitragen, nicht durch Dauerreden oder völlige Passivität.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3b838c1a-69b1-4328-9785-cd16d57ae3b6', 'de', 'Sie erzählt von einer Reise. Du warst auch schon dort. Wie könntest du reagieren?', '["Ihr alles erzählen, was du auf deiner Reise gemacht hast", "„Ja, da war ich auch“ sagen und aufhören", "Einen Satz dazu sagen und sie dann einladen, mehr zu erzählen"]'::jsonb, 'Ein kurzer Beitrag und dann Raum für sie hält den Schwung auf beiden Seiten.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2760f510-bd8b-4ac3-bab9-6e67951fb689', 'de', 'Warum bringt sie sich weniger ein, wenn du das Gespräch dominierst?', '["Sie kommt nicht dazu, etwas beizutragen", "Es wird ein einseitiger Monolog", "Es zeigt, dass du aktiv zuhörst"]'::jsonb, 'Wer dominiert, lässt ihr keinen Raum und bringt das Gleichgewicht durcheinander.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6e149fa3-93c4-42b2-9c8e-f7f88712cc49', 'de', 'Sie hat dir eine schwierige Entscheidung erklärt und schaut dich an. Was ist die beste Reaktion?', '["Sie sofort beruhigen", "Gleich einen Rat geben", "Kurz innehalten, Blickkontakt halten und dann antworten", "Das Thema wechseln, um die Stimmung aufzulockern"]'::jsonb, 'Eine kurze Pause zeigt, dass du ihre Worte auf dich wirken lässt, und lädt zu mehr Tiefe ein.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f100da89-837b-4ce4-89f0-13a05418c184', 'de', 'Du stellst eine nachdenkliche Frage. Sie überlegt, bevor sie antwortet. Was solltest du tun?', '["Einspringen und ihr helfen", "Die Frage umformulieren", "Noch eine Frage hinterherschieben", "Den Raum halten und sie nachdenken lassen"]'::jsonb, 'Wenn du sie ohne Druck nachdenken lässt, zeigst du Geduld und Selbstbewusstsein.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('af284377-c4c0-42ca-a6f4-112ce777e549', 'de', 'Wann wirkt Stille im Gespräch am besten?', '["Nachdem sie etwas Persönliches erzählt hat", "Wenn du nicht weißt, was du sagen sollst", "Direkt bevor du etwas Durchdachtes sagst", "Um gar nichts beitragen zu müssen"]'::jsonb, 'Stille wirkt, wenn sie Raum zum Nachdenken gibt oder Gewicht verleiht, nicht wenn sie Beteiligung ersetzt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5d75efc2-36fb-47a3-9f27-cb0833551415', 'de', 'Was ist Subtext in einem Gespräch?', '["Die genauen Worte, die gesagt werden", "Die emotionale Bedeutung hinter den Worten", "Nur die Lautstärke ihrer Stimme", "Die Länge ihrer Sätze"]'::jsonb, 'Der Subtext ist die Lücke zwischen den Worten und dem Gefühl dahinter. Geh darauf ein.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9fe24bb8-edce-4a11-ac05-37dcfca6822d', 'de', 'Sie sagt leise und unsicher: „Ich bin gerade erst hergezogen.“ Was ist eine einfühlsame Antwort?', '["„Woher bist du hergezogen?“", "„Gefällt’s dir bisher?“", "„Das kann ganz schön viel sein. Wie läuft das Ankommen so?“", "„Was machst du beruflich?“"]'::jsonb, 'Diese Antwort geht auf die Gefühlsebene ein, die in ihrem Tonfall mitschwingt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4434c17e-e1bd-4981-8ea6-566ffaae5de4', 'de', 'Welche Fehler verhindern, dass du den Subtext hörst?', '["Nur auf Schlüsselwörter hören", "Deine nächste Frage planen", "Auf Tonfall und Tempo achten"]'::jsonb, 'Den Subtext überhörst du, wenn du aufs Ausfragen statt aufs Dasein konzentriert bist. Sei präsent.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('69b81da3-8a21-43e7-9c1f-52aedcb7f44f', 'de', 'Was heißt es, zuzuhören, um zu verstehen?', '["Höflich warten, bis du dran bist", "Eine durchdachte Antwort vorbereiten, während sie redet", "Allem zustimmen, was sie sagt", "Ganz bei dem sein, was sie dir mitteilt"]'::jsonb, 'Zuhören, um zu verstehen, heißt: Verstehen geht vor Vorbereiten.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('94878e49-fd86-4e6f-8398-cdb055f272a3', 'de', 'Warum schwächt es die Verbindung, wenn du deine Antwort planst, während sie redet?', '["Es bremst das Gespräch", "Du klingst dadurch einstudiert", "Es gibt mehr Stille", "Es lenkt deine Aufmerksamkeit von dem ab, was sie meint"]'::jsonb, 'Vorausplanen lenkt deinen Fokus nach innen, und du verpasst Zwischentöne und Subtext.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e596b988-c6fd-4182-add2-2c2b0eeb4cc4', 'de', 'Welche Reaktionen zeigen, dass du zugehört hast, um zu verstehen?', '["Sofort Lösungen anbieten", "Das Gefühl benennen, das sie angedeutet hat", "Kurz innehalten, bevor du antwortest", "Direkt an ihren letzten Satz anknüpfen"]'::jsonb, 'Verstehen kommt vom Dasein, nicht vom Problemlösen oder davon, deine Einsichten vorzuführen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5e09607d-070f-41c5-af20-c696a61f1329', 'de', 'Wozu dient es, ihre Antwort zu würdigen, bevor du weiterredest?', '["Um zu zeigen, dass ihre Worte angekommen sind und etwas bedeuten", "Um das Gespräch bewusst zu verlangsamen", "Um emotional intelligent zu klingen", "Um keine Nachfragen stellen zu müssen"]'::jsonb, 'Wenn du sie würdigst, zeigst du, dass ihre Botschaft angekommen ist, bevor das Gespräch weitergeht.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0af9f869-b543-4bea-bfe5-e3c0c0722302', 'de', 'Sie sagt: „Meine Schwester und ich sehen uns kaum noch.“ Beste Reaktion?', '["„So ist das Leben.“", "„Wie alt ist sie?“", "„Entfernung kann echt schwer sein. Redet ihr oft miteinander?“", "„Wo wohnt sie jetzt?“"]'::jsonb, 'Wenn du erst das Gefühl benennst und dann fragst, bleibt der Moment menschlich.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0810f6d9-5a61-4b89-b159-0607132c5f66', 'de', 'Welche Aussagen würdigen das, was sie gesagt hat?', '["„Das klingt, als hätte dich das einiges an Mühe gekostet.“", "„Warum hast du das gemacht?“", "„Ich versteh, warum dir das wichtig war.“", "„Cool.“"]'::jsonb, 'Würdigen heißt, die Bedeutung oder Mühe anzuerkennen, nicht nur den Inhalt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8e246a4f-c248-490c-956f-77029e0a2ad4', 'de', 'Was sind nonverbale Signale des Zuhörens?', '["Körpersprache, die Anteilnahme und Aufmerksamkeit zeigt", "Gesichtsausdrücke, die zeigen, wie dich das Gesagte berührt", "Veränderungen der Haltung, die aktives Zuhören zeigen", "Alle oben genannten"]'::jsonb, 'Nonverbale Signale zeigen, dass du da bist und ihre Worte aufnimmst.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('61372c16-e1e3-47b9-b21c-d9331ef4e852', 'de', 'Sie erzählt eine Geschichte und wird immer lebhafter. Welche nonverbalen Signale passen am besten?', '["Reglos dasitzen, um nicht abzulenken", "Lächeln und eine lebendige Mimik", "Wegschauen, um ihr Raum zu geben", "Ermutigende Worte, ohne dich zu bewegen"]'::jsonb, 'Wenn du ihre Energie körperlich aufnimmst, zeigst du, dass du ihre Geschichte mitfühlst.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9fcc9a77-636d-4e32-833f-dd1e41b91be5', 'de', 'Welche Signale zeigen Ablenkung?', '["Ein ausdrucksloses Gesicht", "Ein abgewandter Körper", "Ihre Mimik spiegeln", "Sich im Raum umschauen"]'::jsonb, 'Reglosigkeit ohne Reaktion wirkt oft desinteressiert.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1e90c6c9-0d3b-47fc-b3ac-599c201f184d', 'de', 'Woran solltest du dich am Anfang vor allem anpassen?', '["An die emotionale Tiefe", "An das Sprechtempo", "An Lautstärke und Energie", "Alle oben genannten"]'::jsonb, 'Am Anfang entsteht Wohlgefühl, wenn du dich an emotionale Tiefe, Tempo und Energie anpasst.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6886b3ac-3f9a-4fba-ad87-515db908bb79', 'de', 'Sie erzählt emotional von etwas, das gerade passiert ist. Was könntest du zuerst tun?', '["Mitfühlend auf ihren emotionalen Ton eingehen", "Mit praktischen Ratschlägen antworten", "Zu einer lustigen Geschichte wechseln", "Sachliche Fragen stellen"]'::jsonb, 'Greif ihren Ton auf, um zu zeigen, dass ihr auf einer Wellenlänge seid, bevor du woandershin lenkst.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('003c10ec-d480-4896-916d-26f2d942ba10', 'de', 'Warum hilft es, dich erst an ihre Tiefe und ihren Stil anzupassen, um eine Verbindung aufzubauen?', '["Es signalisiert Ähnlichkeit und beruhigt ihr Nervensystem", "Es zeigt, dass du auf ihre Energie eingestimmt bist", "Es verringert die Reibung, die entsteht, wenn ihr auf verschiedenen Ebenen seid", "Es führt sofort zu tieferen Themen"]'::jsonb, 'Anpassen bringt euch auf eine Wellenlänge, und der nächste Schritt fühlt sich natürlich an.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3327c759-7a65-49ec-96b3-d70b813c73ef', 'de', 'Wie erzählst du eine Geschichte am wirkungsvollsten?', '["Weniger Persönliches erzählen", "Gefühle ohne Zusammenhang teilen", "Erlebnisse mit Abstand und einem Ergebnis erzählen", "Verletzlichkeit komplett vermeiden"]'::jsonb, 'Wirkungsvolles Erzählen enthält eine Einordnung und ein Ergebnis. Erzähl, was du daraus gelernt hast.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c32cb2cd-cf15-4d66-aa1f-8bc019d02b51', 'de', 'Am Anfang des Gesprächs fragt sie: „Was machst du so?“ Welche Antwort ist am besten abgestimmt?', '["„Ich arbeite in der Tech-Branche, aber ich hasse es und weiß nicht, was ich stattdessen machen will.“", "„Ich arbeite in der Tech-Branche. Ist anstrengend, aber ich lerne viel über Disziplin.“", "„Das ist kompliziert. Ich red nicht so gern darüber.“"]'::jsonb, 'Diese Antwort ist ehrlich und zeigt trotzdem Abstand. Sie weckt Neugier, keine Sorge.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2924bec5-27b6-4372-95e0-97a1b87cd7f5', 'de', 'Warum ist es am Anfang besser, Verarbeitetes zu teilen statt Unverarbeitetes?', '["Es zeigt Selbstreflexion und Entwicklung", "Es lädt ihr keine emotionale Last auf", "Es lädt zu Nähe ein, ohne Druck zu machen", "Es lädt ungelöste Probleme bei ihr ab, um Mitleid zu bekommen"]'::jsonb, 'Verarbeitete Erlebnisse schaffen Verbindung, unverarbeitete sorgen für Unbehagen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('72b691fd-5105-42a5-b902-f35bd796089d', 'de', 'Was ist das Hauptziel, wenn du im Gespräch eine Geschichte erzählst?', '["Sie mit deiner Lebensgeschichte beeindrucken", "Mit ihren Geschichten mithalten", "Die Zeit füllen, bis sie wieder redet", "Etwas Bedeutsames über dich zeigen"]'::jsonb, 'Ein klarer, ehrlicher Ausschnitt hilft ihr, dich schnell zu verstehen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('26a750bf-98fb-4c3c-a099-407b3b3aabb9', 'de', 'Sie fragt, wie du zu deinem jetzigen Job gekommen bist. Was könntest du erzählen?', '["Deinen ganzen Werdegang von der Schule bis heute", "Nur deine jetzige Stelle, ohne Zusammenhang", "Einen entscheidenden Moment, der dich die Richtung wechseln ließ"]'::jsonb, 'Konzentrier dich auf einen bedeutsamen Moment. So zeigst du klar, wer du bist, und sie bleibt dabei.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2330422b-5fb8-4763-a6cc-a1631f85f12d', 'de', 'Was braucht eine Geschichte, die fesselt?', '["Einen kurzen Einstieg für den Zusammenhang", "Einen Konflikt oder Spannung, damit etwas auf dem Spiel steht", "Ein Ergebnis oder eine Erkenntnis", "Genaue Daten und Namen"]'::jsonb, 'Konzentrier dich auf das, was sie verstehen soll, nicht auf alles, was passiert ist.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1ce28b32-b0c8-4221-b1ff-d3645dd9b96d', 'de', 'Warum schaffen Geschichten ohne Bezug zu ihr Distanz statt Verbindung?', '["Du wirkst selbstbezogen und nicht an ihr interessiert", "Du hast von dir erzählt, ohne sie einzubeziehen", "Sie wartet, bis sie dran ist, statt sich auf deine Geschichte einzulassen"]'::jsonb, 'Erzählen ohne Bezug schafft Distanz. Frag nach ihrer Sicht, damit die Verbindung lebendig bleibt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3f38e00a-0c18-4520-94c4-258ed755d84d', 'de', 'Welcher Schluss stellt den Bezug zu ihr her? Du: „Als ich hergezogen bin, waren die ersten Monate ziemlich einsam.“', '["„Na ja, am Ende hat’s für mich geklappt.“", "„Die Stadt ist am Anfang hart.“", "„Umziehen ist immer schwer.“", "„Wie läuft das Ankommen bei dir bisher?“"]'::jsonb, 'Wenn du direkt nach ihrer Sicht fragst, wird aus deinem Erlebnis eine Gemeinsamkeit.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d6f93781-4c91-4d3e-835b-28dd4c18773b', 'de', 'Wie kannst du bei deinen Geschichten den Bezug zu ihr herstellen?', '["Fragen, wie sie mit der Situation umgehen würde, die du beschrieben hast", "Sie mit etwas verbinden, das sie vorhin erwähnt hat", "Ihr ein Kompliment zu einer passenden Eigenschaft oder Sichtweise machen"]'::jsonb, 'Verbindung entsteht, wenn deine Geschichte eine Brücke ist und kein Schlusspunkt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('445fcfa0-4ff7-4518-ac38-f732d3f82c0a', 'de', 'Sie erzählt bereitwillig Persönliches und lacht viel. Was zeigt das?', '["Sie ist nur höflich", "Die Verbindung ist stark genug, um zum Abschluss zu kommen", "Sie will, dass du gehst", "Das Gespräch ist noch oberflächlich"]'::jsonb, 'Dass sie freiwillig erzählt und Energie zeigt, heißt: Der Moment ist reif für den Abschluss.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('22126888-2232-418e-83ad-f3149c24f572', 'de', 'Sie antwortet herzlich und führt aus, was du sagst. Was zeigt das?', '["Die Verbindung ist stark genug, um zum Abschluss zu kommen", "Sie erträgt das Gespräch", "Sie will es kurz halten", "Das Gespräch ist noch oberflächlich"]'::jsonb, 'Herzlichkeit und ausführliche Antworten zeigen, dass sie sich stark einbringt. Der Moment ist reif für den Abschluss.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8c9143a9-92d6-4ec0-bd1d-cc131e69c354', 'de', 'Woran erkennst du, dass der Moment reif für den Abschluss ist?', '["Sie antwortet kurz und höflich", "Sie bringt mehr ein als nötig", "Sie stellt Fragen über dich", "Sie bleibt dabei und ist neugierig"]'::jsonb, 'Wenn sie sich einbringt, nach dir fragt und dabeibleibt, ist der Moment reif für den Abschluss.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('372fbba5-b4e8-4738-9cf6-186872aed9ae', 'de', 'Warum solltest du deinen Abschied mit etwas verknüpfen, worüber ihr geredet habt?', '["Um aufmerksam zu wirken", "Um einen natürlichen Grund zu haben, dich wieder zu melden", "Um zu beweisen, dass du zugehört hast", "Um sofort die Anziehung zu steigern"]'::jsonb, 'Ein Bezug zu einem gemeinsamen Detail gibt euch einen natürlichen Grund, wieder Kontakt aufzunehmen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4bf82e54-bc68-47b4-954e-9a2f34ad7cee', 'de', 'Ihr hattet ein gutes Gespräch über ihre anstehende Reise. Wie verabschiedest du dich am besten?', '["„Schön, dich kennengelernt zu haben. Mach’s gut.“", "„Ich lass dich mal weitermachen.“", "Dich schnell verabschieden, um Peinlichkeit zu vermeiden", "Die Reise aufgreifen und vorschlagen, später weiterzureden"]'::jsonb, 'Ein Rückbezug auf etwas, das ihr wichtig war, hält die Begegnung über den Abschied hinaus lebendig.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b6859e08-892e-4454-a9e6-c9d9f7f344eb', 'de', 'Welche Details eignen sich am besten, um eine Begegnung zu beenden?', '["Ein Plan, den sie erwähnt hat", "Ein gemeinsamer Witz", "Eine neutrale Beobachtung", "Etwas, worauf sie sich gefreut hat"]'::jsonb, 'Emotionale oder gemeinsame Momente schaffen mehr Zusammenhang als neutrales Füllmaterial.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('10646abd-5ffe-4d87-9ebb-9d70bfea0218', 'de', 'Worüber entscheidet sie, wenn du zum Abschluss kommst?', '["Ob du Beziehungsmaterial bist", "Ob sich der nächste Schritt angenehm anfühlt", "Ob du anders bist als andere Männer", "Ob sie etwas Ernstes will"]'::jsonb, 'Ein frühes Ja hat mit Wohlgefühl zu tun, nicht mit Verbindlichkeit. Mach den nächsten Schritt leicht.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8d044d58-aac0-440d-9742-83bb3888a6e8', 'de', 'Lockeres Gespräch auf dem Markt. Gute Stimmung. Wie kommst du am besten zum Abschluss?', '["„Wir sollten mal zusammen essen gehen.“", "„Normalerweise mach ich so was nicht, aber krieg ich deine Nummer?“", "„Ich schick dir den Laden, über den wir geredet haben.“", "„Hast du am Wochenende Zeit?“"]'::jsonb, 'Das führt den Moment fort, ohne eine Verpflichtung daraus zu machen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8a141571-c267-4806-9868-387cdb482491', 'de', 'Welche Abschlüsse machen wenig Druck, sodass ihr ein Ja leichtfällt?', '["„Ich schick dir den Laden, den wir erwähnt haben.“", "„Lass uns für morgen ein Abendessen planen.“", "„Lass uns das ein andermal weiterführen.“", "„Darf ich dich diesen Freitag ausführen?“"]'::jsonb, 'Diese Varianten laden zum Weitermachen ein, ohne eine Zusage zu verlangen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('66ba6667-2abd-42f6-a901-d96277d04433', 'de', 'Wie wird aus einer Frage ein selbstverständlicher Abschluss?', '["„Hättest du Lust auf einen Kaffee?“ wird zu „Lass uns einen Kaffee trinken gehen.“", "„Darf ich deine Nummer haben?“ wird zu „Was ist deine Nummer?“", "„Willst du mich wiedersehen?“ wird zu „Lass uns wiedersehen.“", "Alle oben genannten"]'::jsonb, 'Selbstverständliche Abschlüsse funktionieren, weil sie das Zögern aus dem Moment nehmen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d70c3efb-944b-4b7a-82a9-48ba274ccb86', 'de', 'Warum schwächt ein Abschluss, bei dem du um Erlaubnis fragst, oft ein gutes Gespräch?', '["Er klingt zu förmlich", "Er bringt sie ins Nachdenken, statt sie im Moment zu lassen", "Er lässt dich arrogant wirken", "Er schwächt die emotionale Verbindung"]'::jsonb, 'Fragen laden zum Abwägen ein, und das kann Gefühle unterbrechen, die schon positiv waren.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c0286e42-af7f-43c7-ac69-9ab7c6a2e05a', 'de', 'Welche Sätze sind ein selbstverständlicher Abschluss?', '["„Hättest du vielleicht mal Lust, was zu machen?“", "„Lass uns diese Woche noch einen Kaffee trinken.“", "„Tipp deine Nummer ein, ich schreib dir.“", "„Ist es für dich okay, Nummern zu tauschen?“"]'::jsonb, 'Selbstverständliche Abschlüsse funktionieren, weil sie das Zögern aus dem Moment nehmen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b4f4d3f5-96e1-4f85-964d-0f77451b74c5', 'de', 'Was bedeutet es meistens, wenn die Energie im Gespräch abfällt?', '["Sie hat das Interesse verloren", "Das Gespräch ist gescheitert", "Du hast etwas Falsches gesagt", "Der Schwung hat nachgelassen und braucht eine neue Richtung"]'::jsonb, 'Energietiefs sind normale Übergänge, keine Zeichen von Ablehnung.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8c543af2-ac46-444f-8c77-92edfd929224', 'de', 'Nach einem Themenwechsel werden ihre Antworten kürzer. Was ist eine gute Reaktion?', '["Eine tiefere Frage stellen, um den Schwung zurückzuholen", "Die peinliche Stimmung ansprechen", "Kurz innehalten und zu einem leichteren, neutralen Thema wechseln", "Aufhören zu reden und sie die Richtung ändern lassen"]'::jsonb, 'Ruhiges Umlenken bringt den Rhythmus zurück, ohne Druck zu machen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1cdf68f6-8aa9-43b3-9ce5-b644e615778c', 'de', 'Die Energie kann abfallen, weil:', '["ein Thema ausgeschöpft ist", "jemand ein neutrales oder heikles Thema berührt hat", "sich der Rhythmus ganz natürlich verändert hat", "die Anziehung schlagartig weg ist"]'::jsonb, 'Ein Energieabfall zeigt meist einen Wechsel an, keinen Verlust der Anziehung. Pass Thema oder Rhythmus an.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('39b1d59b-f33e-478c-9666-991b209c27d4', 'de', 'Welche innere Regel hilft am besten, anderer Meinung zu sein, ohne die Verbindung zu verlieren?', '["Ihre Ansichten nie infrage stellen", "Deine Argumente immer vollständig erklären", "Gespräche um jeden Preis locker halten", "Unterschiede verstehen wollen, statt sie zu besiegen"]'::jsonb, 'Verstehen erhält die Verbindung. Gewinnen nicht.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c7c5b822-4135-4f6f-8bdf-de37566401d8', 'de', 'Sie äußert eine Meinung, die du nicht teilst. Was solltest du vermeiden?', '["Fragen: „Wie kommst du darauf?“", "Noch mehr nachlegen, um sie zu überzeugen, dass du recht hast", "Ihre Sicht anerkennen, bevor du deine sagst", "Neugierig auf ihre Sicht bleiben"]'::jsonb, 'Wer seine Sicht durchdrücken will, wirkt schnell streitlustig und bringt den Gesprächsrhythmus durcheinander.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('01a6207d-b8f9-4037-8efa-858f6eca585f', 'de', 'Warum kann eine Meinungsverschiedenheit die Anziehung steigern, wenn du gut damit umgehst?', '["Sie sorgt für Drama", "Sie zeigt Echtheit", "Sie zeigt, dass du nicht um Zustimmung buhlst", "Sie zeigt Überlegenheit"]'::jsonb, 'Menschen reagieren auf Echtheit, nicht auf Versuche, Zustimmung zu gewinnen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('bcc09860-096f-4e3f-af27-42276cd9f883', 'de', 'Warum ist es wichtig, dass sie dich mit positiven Gefühlen verbindet?', '["Gefühle sorgen dafür, dass sie dich stärker mit etwas verbindet", "Positive Gefühle bringen sie dazu, mehr Zeit mit dir verbringen zu wollen", "Beides"]'::jsonb, 'Anziehung entsteht aus dem, wie sie sich in deiner Nähe fühlt, nicht nur aus dem Inhalt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f1e9a61d-15cb-4f8b-af34-a49ba9147cfd', 'de', 'Du merkst, dass das Gespräch schwer wird. Was tust du am besten?', '["Abrupt das Thema wechseln", "Mit Logik oder Ratschlägen kommen", "Etwas Verspieltheit oder Fantasie reinbringen", "Dich für die Stimmung entschuldigen"]'::jsonb, 'Leichtigkeit hebt die Stimmung wieder, ohne den Durchhänger zum Thema zu machen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ed64c038-1dd6-4294-ab5d-a11f9b7c1095', 'de', 'Was hilft im Gespräch, damit sie dich mit positiven Gefühlen verbindet?', '["Euch künftige Erleichterung oder Freude ausmalen", "Verspielt sein, ohne Witze zu erzwingen", "Ihre Sorgen kleinreden", "Fragen stellen, die zum Nachdenken anregen"]'::jsonb, 'Das hebt die Stimmung, ohne das abzuwerten, was sie gerade erlebt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0031e3a0-ef4a-44e3-a000-6ae183b1956c', 'de', 'Warum schwächt eine zu schnelle Antwort oft die Verbindung?', '["Sie klingt einstudiert", "Sie nimmt ihr den Raum weiterzuerzählen", "Sie wirkt zu sachlich", "Sie verkürzt das Gespräch"]'::jsonb, 'Tempo kann den Moment überladen und verhindern, dass sie mehr erzählt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('01f54d1a-679b-4a40-80b2-cdc59c6849ef', 'de', 'Was passiert, wenn du im Gespräch zu oft schweigst?', '["Sie muss das Gespräch allein tragen", "Es wirkt geheimnisvoll", "Es baut Spannung auf", "Es zeigt Selbstbewusstsein"]'::jsonb, 'Schweigen ohne eigenen Beitrag lädt die ganze Arbeit unfair bei ihr ab.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('021ce377-a3dd-4de9-9114-c7227778650f', 'de', 'Sie sagt: „Ich seh das anders“, und macht eine Pause. Was ist der beste nächste Schritt?', '["Sie sanft korrigieren", "Fragen, wie sie zu ihrer Sicht gekommen ist", "Sofort deine Position verteidigen", "Das Thema wechseln, um Reibung zu vermeiden"]'::jsonb, 'Wenn du sie nach ihrer Sicht fragst, bleibt das Gespräch ein Miteinander.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('03069501-c343-419c-9422-a171d3aefb45', 'de', 'Wodurch schaden Meinungsverschiedenheiten der Verbindung?', '["Durch gegensätzliche Ansichten", "Durch starke Meinungen", "Dadurch, dass Rechthaben wichtiger ist als die Verbindung", "Durch ernste Themen"]'::jsonb, 'Nicht die Meinungsverschiedenheit sorgt für Spannung, sondern der Drang, recht zu behalten.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0fb4b26d-dc3b-4250-9c5f-8ff9ea4885aa', 'de', 'Warum funktionieren am Anfang kleine Abschlüsse mit wenig Druck besser?', '["Sie fühlen sich wie eine natürliche Fortsetzung des Moments an", "Sie kann Ja sagen, ohne lange abzuwägen", "Sie wecken ihren Instinkt, ihre Grenzen zu schützen"]'::jsonb, 'Bitten mit wenig Druck senken die Abwehr. Halt sie klein, damit sich ein Ja natürlich anfühlt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('15ae2762-769f-4714-8d54-0a1d42a10930', 'de', 'Was beschreibt nonverbales Zuhören am besten?', '["Deinen Körper sichtbar auf ihre Worte reagieren lassen", "Sie nicht unterbrechen", "Ausdrucksstark schauspielern", "Schweigen"]'::jsonb, 'Zuhören zeigt sich im Körper, bevor es sich in Worten zeigt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1a509b2e-e316-4bf7-a46a-0c9212bf889f', 'de', 'Was lässt einen Abschluss mühelos statt fordernd wirken?', '["Die Frage so stellen, dass ein Ja der einfachste Weg ist", "Mehrere Optionen anbieten, damit sie sich in Kontrolle fühlt", "Die Entscheidung so darstellen, dass die Vorteile im Vordergrund stehen"]'::jsonb, 'Das Ziel ist, dass ihr ein Ja leichtfällt: ohne Druck und ganz einfach.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1b58b79f-3bec-4098-a37d-6b534a17056a', 'de', 'Sie lächelt ganz natürlich und unterbricht, was sie gerade tut, um sich auf dich zu konzentrieren. Was heißt das?', '["Sie ist höflich, hat aber kein Interesse", "Sie braucht erst noch mehr Smalltalk", "Sie bringt sich ein, und der Moment ist reif für den Abschluss", "Sie will das Gespräch beenden"]'::jsonb, 'Ein echtes Lächeln und ungeteilte Aufmerksamkeit zeigen, dass der Moment reif für den Abschluss ist.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1c45a74c-59e6-49a8-abc6-c4f1e648d603', 'de', 'Was bringt den Gesprächsrhythmus durcheinander?', '["Einer redet zu viel, ohne Pause", "Einer verstummt und trägt nichts bei", "Häufige Themenwechsel, bevor ein Thema ausgeschöpft ist", "Alle oben genannten"]'::jsonb, 'Ein guter Rhythmus entsteht, wenn du weißt, wann du redest und wann du aufhörst.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('20617380-7250-45ce-9ef3-db838e43f344', 'de', 'Sie sagt: „Bei der Arbeit war viel los“, atmet dabei aus und sinkt in sich zusammen. Was zeigt das wahrscheinlich?', '["Sie ist gern produktiv", "Sie will einen Rat", "Sie wechselt das Thema", "Sie deutet Erschöpfung oder Stress an"]'::jsonb, 'Nonverbale Signale verraten oft mehr als die Worte selbst.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('26b9d0d1-6a3e-46d5-8be6-4fce70caa793', 'de', 'Sie erzählt, dass sie nächste Woche mit einem Töpferkurs anfängt. Was sind gute Abschiedssätze?', '["„Viel Spaß beim Töpfern!“", "„Töpferkurs! Du musst mir zeigen, was du machst.“", "„Ich will hören, wie die erste Stunde läuft.“", "„Wie cool! Wir sollten mal was zusammen machen.“"]'::jsonb, 'Wenn du an einen Faden anknüpfst, habt ihr einen natürlichen Grund, wieder Kontakt aufzunehmen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('27419754-77e6-40e3-9216-e374c74f4e85', 'de', 'Was ist der Schlüssel zu einem ausgewogenen Gespräch?', '["Fragen mit Beobachtungen und Aussagen mischen", "Nur Fragen stellen, damit es läuft", "Eigene Gedanken und Aufmerksamkeit einbringen", "Sie den ganzen Inhalt liefern lassen"]'::jsonb, 'Ausgewogenheit entsteht, wenn beide etwas beitragen, nicht durch Ausfragen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2bd11bb2-0b86-43aa-b35b-b9370dcdcbdc', 'de', 'Sie scherzt locker über ihren Tag. Was ist die beste Reaktion?', '["Von einem ernsten persönlichen Problem erzählen", "Schweigen und sie führen lassen", "Eine tiefe Frage zu ihren Werten stellen", "Ihren Humor aufgreifen und ein kleines verspieltes Detail ergänzen"]'::jsonb, 'Wenn du ihre Leichtigkeit aufgreifst, bleiben Rhythmus und Schwung erhalten.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('30047758-bc26-4c9c-b253-e6f994f1b01c', 'de', 'Wann ist es angebracht, Unverarbeitetes zu teilen?', '["Wenn schon viel Vertrauen und eine feste Grundlage da sind", "Nie, verarbeite Erlebnisse immer, bevor du sie teilst", "Wenn du schnell emotionale Unterstützung von ihr brauchst"]'::jsonb, 'Unverarbeitetes zu teilen braucht eine Grundlage, die dieses Gewicht tragen kann.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3133663f-3070-4a86-ace7-3cb3f7ad86cc', 'de', 'Sie erzählt seufzend von einer schwierigen Erfahrung. Was solltest du vermeiden?', '["Sagen: „Das klingt hart. Was hat dir geholfen, da durchzukommen?“", "Gleich mit „Hast du es schon mal so probiert?“ kommen", "Sagen: „Ich versteh, warum das schwer war.“", "Fragen: „Wie ging’s dir damit?“"]'::jsonb, 'Ein Rat, ohne erst ihr Gefühl zu würdigen, wirkt, als hättest du sie nicht verstanden.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('31d09412-eae6-4340-9ae4-3e41fb01548a', 'de', 'Sie hat eine Band erwähnt, die ihr beide mögt. Was könntest du zum Abschied tun?', '["„Schön, dich kennengelernt zu haben“ sagen", "Die Band aufgreifen und vorschlagen, Nummern zu tauschen, um euch Musik zu schicken", "Noch eine Frage stellen, die nichts damit zu tun hat"]'::jsonb, 'Nutz beim Abschied ein gemeinsames Detail, um Verbindung und Schwung zu erhalten.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('334df846-2984-4745-ad56-48b235d5dc09', 'de', 'Warum schwächt es die Anziehung, wenn du nur nickst, um keinen Widerspruch zu riskieren?', '["Es wirkt unehrlich", "Es zeigt Unsicherheit oder dass du Zustimmung suchst", "Es nimmt dem Gespräch die Tiefe", "Alle oben genannten"]'::jsonb, 'Wer Unterschieden ausweicht, verschwindet im Hintergrund und verliert an Echtheit.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('33959938-2cf9-429c-889b-15d1b785f535', 'de', 'Was ist der Hauptunterschied zwischen Zuhören, um zu antworten, und Zuhören, um zu verstehen?', '["Fokus auf dich statt Fokus auf sie", "Wie selbstbewusst du bist", "Wie schnell du antwortest", "Wie viel du redest"]'::jsonb, 'Der Unterschied liegt darin, wo deine Aufmerksamkeit während des Gesprächs ist.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('353e58e9-544b-4f89-8b9f-2806e9bbc67f', 'de', 'Warum funktionieren kleine Bitten psychologisch besser als große Vorschläge?', '["Menschen sagen leichter Ja, wenn eine Bitte wenig Druck macht", "Kleine Bitten zeigen Selbstbewusstsein, weil du unabhängig vom Ergebnis bist", "Wenn wenig auf dem Spiel steht, haben beide weniger Angst vor einer Abfuhr"]'::jsonb, 'Bitten mit wenig Druck senken die Abwehr. Halt sie klein, damit sich ein Ja natürlich anfühlt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('35bf5d25-82d5-4369-ade9-a66744b2cd83', 'de', 'Welche Frage an dich selbst hilft dir, die richtige Geschichte auszuwählen?', '["„Ist das beeindruckend?“", "„Erzähl ich auch wirklich alles?“", "„Was ist der eine Punkt, den sie verstehen soll?“", "„Wie lange rede ich schon?“"]'::jsonb, 'Konzentrier dich auf das, was sie verstehen soll, nicht auf alles, was passiert ist.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('36112ad3-3e6a-4b43-8ba4-e67ceaa9859d', 'de', 'Dir fällt ihre außergewöhnliche Handyhülle auf. Welche Reaktion ist eine Beobachtung?', '["„Woher hast du die Handyhülle?“", "„Die Handyhülle ist echt cool.“", "„Bist du zufrieden mit deinem Handy?“", "„Was für ein Modell ist dein Handy?“"]'::jsonb, 'Eine Beobachtung zeigt Aufmerksamkeit und gibt ihr etwas, worauf sie eingehen kann.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3722ef90-5c5e-45fb-bb2f-2f8a5e572077', 'de', 'Was ist der entscheidende Unterschied zwischen Verarbeitetem und Unverarbeitetem?', '["Verarbeitetes ist immer positiv, Unverarbeitetes negativ", "Verarbeitetes sind gelernte Lektionen, Unverarbeitetes ist ungelöster Schmerz", "Verarbeitetes macht Druck, Unverarbeitetes baut Vertrauen auf"]'::jsonb, 'Teil die Lektion, nicht die Wunde, damit sie keine emotionale Last tragen muss.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('37f350f5-2279-4994-9c9e-3ad922169129', 'de', 'Warum verhindert das Anknüpfen an Fäden, dass Smalltalk ermüdend wird?', '["Ihr redet über bedeutsame Themen statt über Oberflächliches", "Wenn du an ihre Fäden anknüpfst, entsteht echter Austausch statt eines erzwungenen Frage-Antwort-Spiels", "Es zeigt Interesse und dass du ihr zugehört hast", "Alle oben genannten"]'::jsonb, 'Das Anknüpfen vertieft Themen, nimmt das Verhörgefühl raus und lässt sie sich mehr einbringen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('38aecf14-80ce-4eef-8327-98612dfd5568', 'de', 'Sie erzählt eine Geschichte, und du hast den Drang, von deiner eigenen Erfahrung zu erzählen. Was tust du am besten?', '["Danach deine Geschichte erzählen", "Dich zurückhalten und erst aufgreifen, was sie erzählt hat", "Das Thema wechseln, um den Schwung zu halten", "Einen Rat geben, um etwas beizutragen"]'::jsonb, 'Wenn du erst ihre Geschichte aufgreifst, bevor du von dir erzählst, bleibt der Fokus darauf, sie zu verstehen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
commit;
